// <auto-generated />
/**
 * The shape of a value, for converting it between the wire (the API's property names, dates as strings) and
 * the TypeScript models (the naming strategy, dates as Date): a model name, a date, an array, a dictionary
 * (its keys are data and stay as they are) or a union of models.
 */
export type WireShape =
  | string
  | { readonly date: 'date' | 'date-time' }
  | { readonly array: WireShape }
  | { readonly record: WireShape }
  | { readonly union: readonly WireShape[] };

/** The shapes of an operation's request body, response (or stream item) and declared error bodies. */
export interface WireShapes {
  readonly body?: WireShape;
  readonly response?: WireShape;
  readonly errors?: Readonly<Record<string, WireShape>>;
}

type WireProperties = Readonly<Record<string, readonly [name: string, shape?: WireShape]>>;

/** Per model: the wire name of each property to rename, its TypeScript name and the shape of its value. */
const wireModels: Readonly<Record<string, WireProperties>> = {
  ItemLog: {
    timestamp: ['timestamp', { date: 'date-time' }],
  },
};

const tsModels = new Map<string, WireProperties>();

/** The same properties keyed by their TypeScript name (for renaming the other way). */
function tsProperties(model: string): WireProperties | undefined {
  const wire = wireModels[model];
  if (!wire) {
    return undefined;
  }

  let ts = tsModels.get(model);
  if (!ts) {
    ts = Object.fromEntries(Object.entries(wire).map(([wireName, [tsName, shape]]) => [tsName, [wireName, shape] as const]));
    tsModels.set(model, ts);
  }

  return ts;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }

  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

/** A declared date: a string from the wire becomes a Date; a Date is written as yyyy-MM-dd (format: date) or ISO 8601. */
function convertDate(value: unknown, kind: 'date' | 'date-time', toWire: boolean): unknown {
  if (toWire) {
    if (!(value instanceof Date)) {
      return value;
    }

    return kind === 'date' ? value.toISOString().slice(0, 10) : value.toISOString();
  }

  if (typeof value !== 'string') {
    return value;
  }

  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? value : parsed;
}

function convert(value: unknown, shape: WireShape | undefined, toWire: boolean): unknown {
  if (shape !== undefined && typeof shape === 'object' && 'date' in shape) {
    return convertDate(value, shape.date, toWire);
  }

  if (shape === undefined || value === null || typeof value !== 'object') {
    return value;
  }

  if (typeof shape === 'string') {
    if (!isPlainObject(value)) {
      return value;
    }

    const properties = toWire ? tsProperties(shape) : wireModels[shape];
    if (!properties) {
      return value;
    }

    const result: Record<string, unknown> = {};
    for (const [key, item] of Object.entries(value)) {
      const property = properties[key];
      if (property) {
        result[property[0]] = convert(item, property[1], toWire);
      } else {
        result[key] = item;
      }
    }

    return result;
  }

  if ('array' in shape) {
    return Array.isArray(value) ? value.map((item) => convert(item, shape.array, toWire)) : value;
  }

  if ('record' in shape) {
    return isPlainObject(value)
      ? Object.fromEntries(Object.entries(value).map(([key, item]) => [key, convert(item, shape.record, toWire)]))
      : value;
  }

  // A union: the member model the object has the most keys of.
  if (!isPlainObject(value)) {
    return value;
  }

  const keys = Object.keys(value);
  let best: WireShape | undefined;
  let bestScore = 0;
  for (const member of shape.union) {
    const properties = typeof member === 'string' ? (toWire ? tsProperties(member) : wireModels[member]) : undefined;
    const score = properties ? keys.filter((key) => key in properties).length : 0;
    if (score > bestScore) {
      best = member;
      bestScore = score;
    }
  }

  return best === undefined ? value : convert(value, best, toWire);
}

/** Converts a value read from the wire to the TypeScript models (property names, dates). */
export function fromWire<T = unknown>(value: unknown, shape: WireShape | undefined): T {
  return convert(value, shape, false) as T;
}

/** Converts a TypeScript model value to the API's form (property names, dates), for sending it. */
export function toWire(value: unknown, shape: WireShape | undefined): unknown {
  return convert(value, shape, true);
}